import {createSchematicEngine,chicagoOverviewDrawing,stationBarDrawing} from './schematic.js?v=amtrak-5';
export const NORTHEAST_SERVICES=['Acela','Northeast Regional','Vermonter','Silver Meteor','Palmetto','Carolinian','Crescent','Cardinal'];
const services=new Set(NORTHEAST_SERVICES),codes=new Set(['WAS','NCR','BWI','BAL','ABE','NRK','WIL','PHL','PHN','CWH','TRE','PJC','NBK','MET','EWR','NWK','NYP']),pair=f=>[f.properties.from,f.properties.to].sort().join('|');
